import fs from 'node:fs/promises';import path from 'node:path';
const findings=[],files=[];async function walk(dir){for(const e of await fs.readdir(dir,{withFileTypes:true})){const p=path.join(dir,e.name);if(e.isDirectory())await walk(p);else files.push(p);}}await walk('static');await walk('public-domain');files.push('dist/worker.mjs');for(const file of files){if(/\.(map|sql|sqlite3?|db|bak|pem|key)$|(?:^|\/)\.env(?!\.example$)/i.test(file))findings.push({file,kind:'private artifact path'});if(/\.(?:webp|png|jpg|jpeg|mp4|gif|ico|woff2?)$/i.test(file))continue;const text=await fs.readFile(file,'utf8');for(const[kind,pattern]of [['private key',/-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/],['provider secret',/\bsb_secret_[A-Za-z0-9_-]{20,}|\bgh[pousr]_[A-Za-z0-9]{30,}|\bAKIA[A-Z0-9]{16}\b/]])if(pattern.test(text))findings.push({file,kind});for(const jwt of text.matchAll(/\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\b/g)){try{const data=JSON.parse(Buffer.from(jwt[0].split('.')[1],'base64url'));if(data.role==='service_role')findings.push({file,kind:'service role JWT'});}catch{}}if(/sourceMappingURL=/.test(text)&&file.startsWith('static/'))findings.push({file,kind:'source map reference'});}
console.log(JSON.stringify({scanned:files.length,findings},null,2));if(findings.length)process.exitCode=1;
